    /// java: private static List<Option<Boolean>> createSlotTextToggles(SkyblockerConfig config)
    pub fn create_slot_text_toggles(config: &compat::Shared<SkyblockerConfig>) -> Vec<Arc<dyn option::Option<bool>>> {
        use crate::de::hysky::skyblocker::utils::container::slot_text_adder::ConfigInformation;
        // java: SlotTextManager.getAdderStream().map(SlotTextAdder::getConfigInformation).filter(Objects::nonNull).distinct()
        //       (`ConfigInformation.equals` compares the id)
        let mut infos: Vec<ConfigInformation> = Vec::new();
        for adder in crate::de::hysky::skyblocker::skyblock::item::slottext::slot_text_manager::SlotTextManager::get_adder_stream() {
            let info = { let __f = compat::dispatch(&adder, |__t| __t.get_config_information()); __f(&adder) };
            if let Some(info) = info {
                if !infos.iter().any(|seen| seen.id() == info.id()) {
                    infos.push(info);
                }
            }
        }
        // java: .map(configInfo -> configInfo.getOption(config))
        let mut options: Vec<Arc<dyn option::Option<bool>>> = infos.iter().map(|info| info.get_option(config)).collect();
        // java: .sorted(Comparator.comparing(option -> option.name().getString())).toList() (`String.compareTo`: UTF-16 order)
        options.sort_by_cached_key(|option| option.name().get_string().encode_utf16().collect::<Vec<u16>>());
        options
    }

    /// java: private static List<Option<Boolean>> createRadialToggles(SkyblockerConfig config)
    pub fn create_radial_toggles(config: &compat::Shared<SkyblockerConfig>) -> Vec<Arc<dyn option::Option<bool>>> {
        // java: RadialMenuManager.getMenuStream().filter(distinctByKey(RadialMenu::getConfigId))
        let mut seen: std::collections::HashSet<String> = std::collections::HashSet::new();
        let mut options: Vec<Arc<dyn option::Option<bool>>> = Vec::new();
        for menu in crate::de::hysky::skyblocker::skyblock::radial_menu::radial_menu_manager::RadialMenuManager::get_menu_stream() {
            let config_id: String = { let __f = compat::dispatch(&menu, |__t| __t.get_config_id()); __f(&menu) };
            if seen.insert(config_id) {
                // java: .map(configInfo -> configInfo.getOption(config))
                let get_option = compat::dispatch(&menu, |__t| __t.get_option());
                options.push(get_option(&menu, config));
            }
        }
        // java: .sorted(Comparator.comparing(option -> option.name().getString())).toList()
        options.sort_by_cached_key(|option| option.name().get_string().encode_utf16().collect::<Vec<u16>>());
        options
    }

    /// java: `WidgetManager.WIDGET_INSTANCES.values().stream().map(w -> w.getInformation().displayName()).toArray(Component[]::new)`
    /// - the first array of the tab HUD screen option's `tags(ArrayUtils.addAll(..))`. A widget without a display name
    /// (Java: a `null` element) adds no tag.
    pub fn widget_display_names() -> Vec<MutableComponent> {
        crate::de::hysky::skyblocker::skyblock::tabhud::screenbuilder::widget_manager::WIDGET_INSTANCES
            .get()
            .values()
            .filter_map(|w| { let __f = compat::dispatch(w, |__t| __t.get_information()); __f(w) }.display_name())
            .collect()
    }
